[HttpPost("upload")]
[Consumes("multipart/form-data")]
[RequestSizeLimit(10 * 1024 * 1024)] // 10 MB
public async Task<ActionResult<FileMetadataDto>> Upload(
    [FromForm] IFormFile file,
    [FromForm] string category,
    IBlobStorage storage,
    CancellationToken ct)
{
    if (file.Length == 0) return BadRequest("Empty file");
    if (!IsAllowedContentType(file.ContentType))
        return BadRequest("Unsupported file type");

    var safeName = Path.GetRandomFileName();
    await using var stream = file.OpenReadStream();
    var url = await storage.UploadAsync(safeName, stream, file.ContentType, ct);

    return Created(url, new FileMetadataDto(safeName, file.Length, category));
}

[HttpPost("batch")]
public async Task<IActionResult> UploadMany([FromForm] List<IFormFile> files)
{
    foreach (var file in files)
    {
        await using var stream = file.OpenReadStream();
        // process each stream
    }
    return Accepted();
}

