[HttpGet("{id:guid}")]
public async Task<IActionResult> Download(Guid id, IFileStore store, CancellationToken ct)
{
    var meta = await store.GetMetadataAsync(id, ct);
    if (meta is null) return NotFound();

    var stream = await store.OpenReadAsync(id, ct);
    return File(stream, meta.ContentType, meta.DownloadName, enableRangeProcessing: true);
}

